\set ON_ERROR_STOP on
begin;
create schema jury_test;
create function jury_test.check_that(ok boolean, label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAILED: %',label; end if; raise notice 'PASS: %',label; end $$;
create function jury_test.expect_error(statement text, fragment text) returns void language plpgsql as $$ declare caught boolean:=false; begin begin execute statement; exception when others then caught:=true; if position(fragment in sqlerrm)=0 then raise exception 'Unexpected error for %: %',statement,sqlerrm; end if; end; if not caught then raise exception 'Expected rejection: %',statement; end if; raise notice 'PASS: rejected %',fragment; end $$;
grant usage on schema jury_test to authenticated,anon;
grant execute on all functions in schema jury_test to authenticated,anon;
insert into auth.users(id,raw_user_meta_data) select ('00000000-0000-0000-0000-'||lpad(i::text,12,'0'))::uuid,jsonb_build_object('display_name','Juror '||i) from generate_series(1,7)i;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select set_config('jury_test.room',public.jury_open_room('glass-hour',true,null)::text,true);
select jury_test.expect_error('select public.jury_start_room('''||current_setting('jury_test.room')||''')','six seats');
select jury_test.expect_error('select public.jury_open_room(''glass-hour'',true,null)','already have a seat');
select set_config('jury_test.code',(public.jury_room_snapshot(current_setting('jury_test.room')::uuid)->>'code'),true);
do $$ begin for i in 2..6 loop perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-'||lpad(i::text,12,'0'),true); perform public.jury_open_room('glass-hour',true,current_setting('jury_test.code')); end loop; end $$;
select jury_test.check_that(jsonb_array_length(public.jury_room_snapshot(current_setting('jury_test.room')::uuid)->'jurors')=6,'six real members');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000007',true);
select jury_test.expect_error('select public.jury_open_room(''glass-hour'',true,'''||current_setting('jury_test.code')||''')','room is full');
select jury_test.expect_error('select public.jury_room_snapshot('''||current_setting('jury_test.room')||''')','not available');
select jury_test.check_that((select count(*)=0 from public.rooms),'outsider cannot read rooms through RLS');
select jury_test.expect_error('update public.profiles set points=9999','permission denied');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select jury_test.expect_error('select public.jury_start_room('''||current_setting('jury_test.room')||''')','Only the host');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.jury_start_room(current_setting('jury_test.room')::uuid);
select jury_test.expect_error('select public.jury_vote('''||current_setting('jury_test.room')||''',''responsible'',false,'''')','Review every exhibit');
select jury_test.expect_error('select public.jury_send_message('''||current_setting('jury_test.room')||''',''early message'',null)','Discussion is not open');
do $$ begin for i in 1..6 loop perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-'||lpad(i::text,12,'0'),true);for j in 1..4 loop perform public.jury_review(current_setting('jury_test.room')::uuid,'E'||j);end loop;perform public.jury_vote(current_setting('jury_test.room')::uuid,'notResponsible',false,'');end loop;end $$;
select jury_test.check_that(public.jury_room_snapshot(current_setting('jury_test.room')::uuid)->>'stage'='deliberation','six initial votes open deliberation');
select jury_test.check_that((select count(*)=1 from public.ballots),'RLS reveals only own initial ballot');
select jury_test.check_that(public.jury_room_snapshot(current_setting('jury_test.room')::uuid)->>'responsible_count' is null,'no premature aggregate');
select jury_test.expect_error('select public.jury_vote('''||current_setting('jury_test.room')||''',''responsible'',false,'''')','already sealed');
select jury_test.expect_error('select public.jury_begin_final('''||current_setting('jury_test.room')||''')','host opens');
select public.jury_send_message(current_setting('jury_test.room')::uuid,'The access log identifies a key, not the person holding it.','E1');
select jury_test.expect_error('select public.jury_send_message('''||current_setting('jury_test.room')||''',''A second thought'',''BAD'')','Exhibit not found');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.jury_begin_final(current_setting('jury_test.room')::uuid);
select jury_test.expect_error('select public.jury_vote('''||current_setting('jury_test.room')||''',''responsible'',true,''short'')','20–2,000');
do $$ begin for i in 1..5 loop perform set_config('request.jwt.claim.sub','00000000-0000-0000-0000-'||lpad(i::text,12,'0'),true);perform public.jury_vote(current_setting('jury_test.room')::uuid,case when i<=3 then 'responsible' else 'notResponsible' end,true,'I considered the access evidence and the uncertainty in the witness account.');end loop;end $$;
select jury_test.check_that(public.jury_room_snapshot(current_setting('jury_test.room')::uuid)->>'responsible_count' is null,'five final votes still hide counts');
select jury_test.check_that((select count(*)=0 from public.case_history),'incomplete round awards no points');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000006',true);
select public.jury_vote(current_setting('jury_test.room')::uuid,'notResponsible',true,'The access record does not identify the person, so a reasonable alternative remains.');
select jury_test.check_that(public.jury_room_snapshot(current_setting('jury_test.room')::uuid)->>'stage'='complete','six final ballots close the room');
select jury_test.check_that((public.jury_room_snapshot(current_setting('jury_test.room')::uuid)->>'responsible_count')::int=3,'aggregate handles a tied jury');
select jury_test.check_that((select count(*)=2 from public.ballots),'other jurors ballots remain private after completion');
select jury_test.check_that((select points=120 from public.profiles where id=auth.uid()),'points computed on server for citation and review');
select jury_test.check_that((select payload->>'outcome'='Hung jury' from public.case_history where user_id=auth.uid()),'case journal stores hung jury result');
select jury_test.expect_error('select public.jury_vote('''||current_setting('jury_test.room')||''',''responsible'',true,''A second sufficiently long explanation.'')','already sealed');
select jury_test.check_that((select points=120 from public.profiles where id=auth.uid()),'retry cannot duplicate points');
select jury_test.check_that(jsonb_array_length(public.jury_player_snapshot()->'history')=1,'player snapshot restores history');
reset role;
select jury_test.check_that((select count(*)=6 from public.case_history),'all six histories recorded exactly once');
select jury_test.check_that((select sum(points)=620 from public.profiles),'total points match six contributions');
set local role anon;
select jury_test.expect_error('select public.jury_rankings()','permission denied');
select jury_test.expect_error('select public.jury_player_snapshot()','permission denied');
reset role;
set local role anon;
select jury_test.expect_error('select public.jury_delete_my_account()','permission denied');
reset role;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000007',true);
select set_config('jury_test.lobby',public.jury_open_room('glass-hour',true,null)::text,true);
select set_config('jury_test.lobby_code',(public.jury_room_snapshot(current_setting('jury_test.lobby')::uuid)->>'code'),true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000002',true);
select public.jury_open_room('glass-hour',true,current_setting('jury_test.lobby_code'));
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000007',true);
select public.jury_delete_my_account();
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000001',true);
select public.jury_delete_my_account();
reset role;
select jury_test.check_that((select count(*)=0 from public.profiles where id in ('00000000-0000-0000-0000-000000000001','00000000-0000-0000-0000-000000000007')),'deleted accounts leave no profile');
select jury_test.check_that((select host_id is null from public.rooms where id=current_setting('jury_test.room')::uuid),'finished room survives its deleted host');
select jury_test.check_that((select host_id='00000000-0000-0000-0000-000000000002' from public.rooms where id=current_setting('jury_test.lobby')::uuid),'waiting room passes hosting on before deletion');
select jury_test.check_that((select count(*)=5 from public.case_history),'other jurors keep their history');
rollback;
